// The web Worker's entry (`main` in wrangler.jsonc): OpenNext's generated
// handler, wrapped with Sentry so every request gets error capture and a
// trace (D1 queries included). Run `build:cloudflare` before `wrangler` sees
// this file — `.open-next/` is a build output.
import * as Sentry from '@sentry/nextjs/cloudflare'

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js'
import { SENTRY_TRACES_SAMPLE_RATE } from './lib/sentry-options'

// OpenNext's Durable Objects. Unbound unless open-next.config.ts enables the
// queue / tag cache, but the classes must stay exported if it ever does.
// prettier-ignore
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by `opennextjs-cloudflare build`
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'

export default Sentry.withSentry(
  (env: CloudflareEnv) => ({
    // Unset → the SDK stays off. `wrangler secret put SENTRY_DSN`.
    dsn: env.SENTRY_DSN,
    tracesSampleRate: SENTRY_TRACES_SAMPLE_RATE,
    // Release comes from the CF_VERSION_METADATA binding (the deployed
    // version id) — no build-time wiring needed.
  }),
  handler as ExportedHandler<CloudflareEnv>,
)
